#include "graph.h"
#include <limits.h>
#include <string.h>
void graph_init(Graph*g,int n){if(!g)return;if(n<0)n=0;if(n>GRAPH_MAX)n=GRAPH_MAX;g->n=n;for(int i=0;i<GRAPH_MAX;i++)for(int j=0;j<GRAPH_MAX;j++)g->w[i][j]=i==j?0:INT_MAX/4;}
void dijkstra(const Graph*g,int s,int d[]){int used[GRAPH_MAX]={0};for(int i=0;i<g->n;i++)d[i]=INT_MAX/4;if(s<0||s>=g->n)return;d[s]=0;for(int k=0;k<g->n;k++){int u=-1;for(int i=0;i<g->n;i++)if(!used[i]&&(u<0||d[i]<d[u]))u=i;if(u<0||d[u]>=INT_MAX/4)break;used[u]=1;for(int v=0;v<g->n;v++)if(g->w[u][v]>=0&&g->w[u][v]<INT_MAX/4&&d[u]+g->w[u][v]<d[v])d[v]=d[u]+g->w[u][v];}}
void bellman_ford(const Graph*g,int s,int d[],int*neg){for(int i=0;i<g->n;i++)d[i]=INT_MAX/4;if(neg)*neg=0;if(s<0||s>=g->n)return;d[s]=0;for(int k=1;k<g->n;k++){int change=0;for(int u=0;u<g->n;u++)for(int v=0;v<g->n;v++)if(d[u]<INT_MAX/4&&g->w[u][v]<INT_MAX/4&&d[u]+g->w[u][v]<d[v]){d[v]=d[u]+g->w[u][v];change=1;}if(!change)break;}for(int u=0;u<g->n;u++)for(int v=0;v<g->n;v++)if(d[u]<INT_MAX/4&&g->w[u][v]<INT_MAX/4&&d[u]+g->w[u][v]<d[v]&&neg)*neg=1;}
void floyd_warshall(const Graph*g,int d[GRAPH_MAX][GRAPH_MAX]){for(int i=0;i<g->n;i++)for(int j=0;j<g->n;j++)d[i][j]=g->w[i][j];for(int k=0;k<g->n;k++)for(int i=0;i<g->n;i++)for(int j=0;j<g->n;j++)if(d[i][k]<INT_MAX/4&&d[k][j]<INT_MAX/4&&d[i][k]+d[k][j]<d[i][j])d[i][j]=d[i][k]+d[k][j];}
int prim_mst(const Graph*g){int key[GRAPH_MAX],used[GRAPH_MAX]={0},sum=0;if(!g->n)return 0;for(int i=0;i<g->n;i++)key[i]=INT_MAX/4;key[0]=0;for(int k=0;k<g->n;k++){int u=-1;for(int i=0;i<g->n;i++)if(!used[i]&&(u<0||key[i]<key[u]))u=i;if(u<0||key[u]>=INT_MAX/4)return -1;used[u]=1;sum+=key[u];for(int v=0;v<g->n;v++)if(g->w[u][v]<key[v])key[v]=g->w[u][v];}return sum;}
int max_flow(const int cap[GRAPH_MAX][GRAPH_MAX],int n,int s,int t){int r[GRAPH_MAX][GRAPH_MAX];memcpy(r,cap,sizeof(r));int total=0,parent[GRAPH_MAX];for(;;){int q[GRAPH_MAX],h=0,z=0;for(int i=0;i<n;i++)parent[i]=-1;parent[s]=s;q[z++]=s;while(h<z&&parent[t]<0){int u=q[h++];for(int v=0;v<n;v++)if(parent[v]<0&&r[u][v]>0){parent[v]=u;q[z++]=v;}}if(parent[t]<0)break;int add=INT_MAX;for(int v=t;v!=s;v=parent[v])if(r[parent[v]][v]<add)add=r[parent[v]][v];for(int v=t;v!=s;v=parent[v]){r[parent[v]][v]-=add;r[v][parent[v]]+=add;}total+=add;}return total;}
static int dfs_match(int u,const int e[GRAPH_MAX][GRAPH_MAX],int right,int seen[],int mate[]){for(int v=0;v<right;v++)if(e[u][v]&&!seen[v]){seen[v]=1;if(mate[v]<0||dfs_match(mate[v],e,right,seen,mate)){mate[v]=u;return 1;}}return 0;}
int max_bipartite_matching(const int e[GRAPH_MAX][GRAPH_MAX],int left,int right){int mate[GRAPH_MAX],n=0;for(int v=0;v<right;v++)mate[v]=-1;for(int u=0;u<left;u++){int seen[GRAPH_MAX]={0};n+=dfs_match(u,e,right,seen,mate);}return n;}
